mapper.select:
select REGIST_SEQNO registSeqNo, REP_TYPE as repType, SUMIT_SEQ repSeqNo, SUBMIT_TIME repDate, SEND_STATUS repStatus,
    SUBMIT_FEEDBACK_STATUS feedbackStatus, STATUS_DATE statusDate, STATUS status, SUBMIT_FEEDBACK_MSG feedbackMsg,
    UNIQUE_CODE as uniqueCode
from CHB_SUB_TWO_VIEW
where 1=1

    AND REP_TYPE=#{repType}


    AND REGIST_SEQNO = #{registSeqNo}


    AND SEND_STATUS = #{repStatus}


    AND SUBMIT_FEEDBACK_STATUS = #{feedbackStatus}


    AND DATE_FORMAT(SUBMIT_TIME, '%Y-%m-%d') >= #{startDate}


    AND DATE_FORMAT(SUBMIT_TIME, '%Y-%m-%d') <= #{endDate}

order by repDate desc
